import dom,rs
HB='''/// 🖊️ Creates a zero-heap scene group that is replaced by its authored variant before any field is copied.
fn empty_node()->DrawNode{DrawNode::Group{transform:SemioTransform::identity(),children:Vec::new()}}
/// 🖊️ Fills one optional scalar in its original slot from borrowed binary octets.
fn option_into<T>(output:&mut Option<T>,reader:&mut store::ByteReader<'_>,read:impl FnOnce(&mut store::ByteReader<'_>)->Result<T,ValueError>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(()),1=>{*output=Some(read(reader)?);Ok(())},_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native optional presence"))}}
/// 🖊️ Fills one optional text field in its original slot from borrowed binary octets.
fn option_text_into(output:&mut Option<String>,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{0=>Ok(()),1=>{*output=Some(String::new());native::reader_text_into(output.as_mut().unwrap(),reader,control)},_=>Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native optional presence"))}}
/// 🖊️ Selects each binary scene node variant in its retained slot before copying its text, octets or children.
fn node_binary_into(output:&mut DrawNode,reader:&mut store::ByteReader<'_>,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;match reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?{
0=>{*output=DrawNode::Path{segments:Vec::new(),style:None};let DrawNode::Path{segments,style}=&mut *output else{unreachable!()};native::binary_list_into(segments,reader,control,limits,entities,||PathSegment::Close,|slot,reader,_,entities|{*slot=segment_binary(reader,entities,limits)?;Ok(())})?;option_text_into(style,reader,control)?;},
1=>{*output=DrawNode::Text{value:String::new(),at:SemioPoint2{x:0.,y:0.},style:None};let DrawNode::Text{value,at,style}=&mut *output else{unreachable!()};native::reader_text_into(value,reader,control)?;*at=point2(reader)?;option_text_into(style,reader,control)?;},
2=>{*output=DrawNode::Group{transform:transform(reader)?,children:Vec::new()};let DrawNode::Group{children,..}=&mut *output else{unreachable!()};native::binary_list_into(children,reader,control,limits,entities,empty_node,|child,reader,control,entities|node_binary_into(child,reader,control,limits,entities))?;},
3=>{*output=DrawNode::Image{at:point2(reader)?,width:f64(reader)?,height:f64(reader)?,mime:String::new(),bytes:Vec::new()};let DrawNode::Image{mime,bytes,..}=&mut *output else{unreachable!()};native::reader_text_into(mime,reader,control)?;native::reader_bytes_into(bytes,reader,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native scene node"))}Ok(())})}
'''
B='''/// 🧩️ Fills the retained drawing root from borrowed binary octets, inserting every style, layer and scene node before its fields.
pub fn binary_into(output:&mut SemioDrawingSnapshot,body:&[u8],control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_binary(body,control,limits)?;let mut reader=store::ByteReader::new(body);if reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?!=1{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"unsupported Drawing native format"))}let mut entities=0;native::entities(&mut entities,1,limits)?;native::reader_text_into(&mut output.schema,&mut reader,control)?;
 output.canvas.width=f64(&mut reader)?;output.canvas.height=f64(&mut reader)?;option_into(&mut output.canvas.background,&mut reader,rgba)?;
 native::binary_list_into(&mut output.styles,&mut reader,control,limits,&mut entities,Default::default,|style,reader,control,_|{native::reader_text_into(&mut style.name,reader,control)?;option_into(&mut style.fill,reader,rgba)?;option_into(&mut style.stroke,reader,rgba)?;option_into(&mut style.stroke_width,reader,f64)?;option_into(&mut style.opacity,reader,f32)})?;
 native::binary_list_into(&mut output.layers,&mut reader,control,limits,&mut entities,Default::default,|layer,reader,control,entities|{native::reader_text_into(&mut layer.id,reader,control)?;native::reader_text_into(&mut layer.name,reader,control)?;layer.visible=boolean(reader.read_u8().map_err(|e|ValueError::new(ValueRefusalKind::InvalidValue,e.to_string()))?)?;node_binary_into(&mut layer.root,reader,control,limits,entities)})?;if reader.remaining()!=0{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native trailing bytes"))}Ok(())}
'''
HT='''/// 🖊️ Fills one optional scalar in its original slot from a bracketed record.
fn optional_into<T>(output:&mut Option<T>,value:&str,control:&mut NativeDecodeControl<'_>,read:impl FnOnce(&str,&mut NativeDecodeControl<'_>)->Result<T,ValueError>)->Result<(),ValueError>{if value=="[0]"{return Ok(())}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native optional presence"))}*output=Some(read(value,control)?);Ok(())}
/// 🖊️ Fills one optional hexadecimal text field in its original slot.
fn optional_text_into(output:&mut Option<String>,value:&str,control:&mut NativeDecodeControl<'_>)->Result<(),ValueError>{if value=="[0]"{return Ok(())}let[tag,value]=native::record(value,control)?;if tag!="1"{return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native optional presence"))}*output=Some(String::new());native::hex_text_into(output.as_mut().unwrap(),value,control)}
/// 🖊️ Selects each text scene node variant in its retained slot before copying its text, octets or children.
fn node_text_into(output:&mut DrawNode,value:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits,entities:&mut usize)->Result<(),ValueError>{control.scoped_depth(64,|control|{native::entities(entities,2,limits)?;let(tag,value)=value.split_at_checked(1).ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native scene tag missing"))?;match tag{
"P"=>{let[segment_fields,style_field]=native::record(value,control)?;*output=DrawNode::Path{segments:Vec::new(),style:None};let DrawNode::Path{segments,style}=&mut *output else{unreachable!()};native::text_list_into(segments,segment_fields,control,limits,entities,||PathSegment::Close,|slot,value,control,entities|{*slot=segment_text(value,control,limits,entities)?;Ok(())})?;optional_text_into(style,style_field,control)?;},
"T"=>{let[text,at_field,style_field]=native::record(value,control)?;*output=DrawNode::Text{value:String::new(),at:SemioPoint2{x:0.,y:0.},style:None};let DrawNode::Text{value:text_slot,at,style}=&mut *output else{unreachable!()};native::hex_text_into(text_slot,text,control)?;*at=point2_text(at_field,control)?;optional_text_into(style,style_field,control)?;},
"G"=>{let[transform,children]=native::record(value,control)?;*output=DrawNode::Group{transform:transform_text(transform,control)?,children:Vec::new()};let DrawNode::Group{children:child_slot,..}=&mut *output else{unreachable!()};native::text_list_into(child_slot,children,control,limits,entities,empty_node,|child,value,control,entities|node_text_into(child,value,control,limits,entities))?;},
"I"=>{let[at,width,height,mime,bytes]=native::record(value,control)?;*output=DrawNode::Image{at:point2_text(at,control)?,width:native::float(width,control)?,height:native::float(height,control)?,mime:String::new(),bytes:Vec::new()};let DrawNode::Image{mime:mime_slot,bytes:byte_slot,..}=&mut *output else{unreachable!()};native::hex_text_into(mime_slot,mime,control)?;native::hex_bytes_into(byte_slot,bytes,control)?;},_=>return Err(ValueError::new(ValueRefusalKind::InvalidValue,"invalid Drawing native scene node"))}Ok(())})}
'''
D='''/// 📝️ Fills the retained drawing root from the borrowed document body, inserting every style, layer and scene node before its fields.
pub fn document_into(output:&mut SemioDrawingSnapshot,body:&str,control:&mut NativeDecodeControl<'_>,limits:SqliteDatabaseLimits)->Result<(),ValueError>{crate::io::sqlite::snapshot::admit_document(body,control,limits)?;let fields=native::fields(body,["schema","canvas","styles","layers"],control)?;let mut entities=0;native::entities(&mut entities,1,limits)?;native::hex_text_into(&mut output.schema,fields[0].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native schema missing"))?,control)?;let[width,height,background]=native::record(fields[1].ok_or_else(||ValueError::new(ValueRefusalKind::InvalidValue,"Drawing native canvas missing"))?,control)?;output.canvas.width=native::float(width,control)?;output.canvas.height=native::float(height,control)?;optional_into(&mut output.canvas.background,background,control,rgba_text)?;
 native::text_list_into(&mut output.styles,fields[2].unwrap_or("[]"),control,limits,&mut entities,Default::default,|style,value,control,_|{let[name,fill,stroke,stroke_width,opacity]=native::record(value,control)?;native::hex_text_into(&mut style.name,name,control)?;optional_into(&mut style.fill,fill,control,rgba_text)?;optional_into(&mut style.stroke,stroke,control,rgba_text)?;optional_into(&mut style.stroke_width,stroke_width,control,native::float)?;optional_into(&mut style.opacity,opacity,control,native::float32)})?;
 native::text_list_into(&mut output.layers,fields[3].unwrap_or("[]"),control,limits,&mut entities,Default::default,|layer,value,control,entities|{let[id,name,visible,root]=native::record(value,control)?;native::hex_text_into(&mut layer.id,id,control)?;native::hex_text_into(&mut layer.name,name,control)?;layer.visible=bool_text(visible)?;node_text_into(&mut layer.root,root,control,limits,entities)})}
'''
p=rs.native("🖊️drawing")
print(dom.apply("🖊️drawing",B,D,remove=("option","node_binary","optional_text","node_text")))
s=open(p,encoding="utf-8").read()
s=s.replace("/// 🧩️ Fills the retained drawing root",HB+"/// 🧩️ Fills the retained drawing root",1)
s=s.replace("/// 📝️ Fills the retained drawing root",HT+"/// 📝️ Fills the retained drawing root",1)
open(p,"w",encoding="utf-8").write(s)
print(dom.fmt("🖊️drawing"))
